package com.seedvaultmemory;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SeedVaultMemoryConfig.GROUP)
public interface SeedVaultMemoryConfig extends Config
{
	String GROUP = "seedvaultmemory";

	@ConfigItem(
		keyName = "groupByCategory",
		name = "Group by category",
		description = "Group seeds under the same categories as the seed vault",
		position = 1
	)
	default boolean groupByCategory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTooltips",
		name = "Show vault count in tooltips",
		description = "When hovering a seed, show how many are in your seed vault",
		position = 2
	)
	default boolean showTooltips()
	{
		return true;
	}
}

package com.seedvaultmemory;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Seed Vault Memory",
	description = "Remembers what's in your seed vault so you can check it from anywhere",
	tags = {"seed", "vault", "farming", "bank", "memory"}
)
public class SeedVaultMemoryPlugin extends Plugin
{
	private static final String CONFIG_KEY = "vault";
	private static final String COLLAPSED_KEY = "collapsedCategories";
	private static final String OTHER_CATEGORY = "Other";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	@Inject
	private SeedVaultMemoryConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SeedVaultTooltipOverlay tooltipOverlay;

	private SeedVaultPanel panel;
	private NavigationButton navButton;

	// The vault for the current account, as last saved
	private SeedVaultSnapshot current;
	// Item id to quantity for the current vault, for quick lookups from the tooltip overlay
	private Map<Integer, Integer> quantities = Collections.emptyMap();

	// Set when the vault interface has been (re)built, so its categories can be read once laid out
	private boolean readCategories;

	@Override
	protected void startUp()
	{
		String collapsed = configManager.getConfiguration(SeedVaultMemoryConfig.GROUP, COLLAPSED_KEY);
		panel = new SeedVaultPanel(
			collapsed == null ? Collections.emptyList() : Text.fromCSV(collapsed),
			names -> configManager.setConfiguration(SeedVaultMemoryConfig.GROUP, COLLAPSED_KEY, Text.toCSV(names)));
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Seed Vault Memory")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(tooltipOverlay);

		clientThread.invokeLater(() ->
		{
			// Item definitions aren't available until the cache has loaded
			if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
			{
				return false;
			}

			setCurrent(load());
			ItemContainer vault = client.getItemContainer(InventoryID.SEED_VAULT);
			if (vault != null)
			{
				save(vault);
				readCategories = true;
			}
			else
			{
				show();
			}
			return true;
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(tooltipOverlay);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		setCurrent(null);
		readCategories = false;
	}

	@Provides
	SeedVaultMemoryConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SeedVaultMemoryConfig.class);
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		setCurrent(load());
		show();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SeedVaultMemoryConfig.GROUP.equals(event.getGroup()) && "groupByCategory".equals(event.getKey()))
		{
			clientThread.invoke(this::show);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.SEED_VAULT)
		{
			save(event.getItemContainer());
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.SEED_VAULT_BUILD)
		{
			readCategories = true;
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (!readCategories)
		{
			return;
		}
		readCategories = false;

		if (current == null)
		{
			return;
		}

		List<SeedVaultSnapshot.Category> categories = readCategories(current.getItems());
		if (categories != null && !categories.equals(current.getCategories()))
		{
			current.setCategories(categories);
			persist();
			show();
		}
	}

	private void save(ItemContainer vault)
	{
		List<SeedVaultSnapshot.Seed> seeds = new ArrayList<>();
		for (Item item : vault.getItems())
		{
			// Skip placeholders, which the vault shows as 0
			if (item.getId() != -1 && item.getQuantity() > 0
				&& itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() == -1)
			{
				seeds.add(new SeedVaultSnapshot.Seed(item.getId(), item.getQuantity()));
			}
		}

		// Keep the categories we already know; new seeds show under "Other" until they're read again
		List<SeedVaultSnapshot.Category> categories = current != null ? current.getCategories() : null;
		setCurrent(new SeedVaultSnapshot(seeds, categories));
		persist();
		show();
	}

	/**
	 * Works out which category each seed is under by matching it to the closest heading above it in the vault.
	 * Uses the positions the vault's script gives each widget, since canvas locations aren't valid here.
	 *
	 * @return the categories in display order, or null if the vault isn't showing every seed (eg. while searching)
	 */
	private List<SeedVaultSnapshot.Category> readCategories(List<SeedVaultSnapshot.Seed> seeds)
	{
		Widget headerLayer = client.getWidget(InterfaceID.SeedVault.CATEGORY_HEADERS);
		Widget objLayer = client.getWidget(InterfaceID.SeedVault.OBJ_LIST);
		if (headerLayer == null || objLayer == null || headerLayer.isHidden() || objLayer.isHidden()
			|| headerLayer.getDynamicChildren() == null || objLayer.getDynamicChildren() == null)
		{
			return null;
		}

		List<Widget> headers = new ArrayList<>();
		for (Widget w : headerLayer.getDynamicChildren())
		{
			if (w != null && w.getType() == WidgetType.TEXT && !w.isSelfHidden()
				&& !Text.removeTags(w.getText()).trim().isEmpty())
			{
				headers.add(w);
			}
		}
		if (headers.isEmpty())
		{
			return null;
		}
		headers.sort(Comparator.comparingInt(Widget::getOriginalY));

		Map<String, List<Integer>> categories = new LinkedHashMap<>();
		for (Widget h : headers)
		{
			categories.putIfAbsent(Text.removeTags(h.getText()).trim(), new ArrayList<>());
		}

		Set<Integer> seen = new HashSet<>();
		for (Widget obj : objLayer.getDynamicChildren())
		{
			if (obj == null || obj.isSelfHidden() || obj.getItemId() <= 0)
			{
				continue;
			}
			// Placeholders become the real seed, so it's in the right category once deposited
			int itemId = itemManager.canonicalize(obj.getItemId());

			int y = obj.getOriginalY();
			Widget header = null;
			for (Widget h : headers)
			{
				if (h.getOriginalY() <= y)
				{
					header = h;
				}
			}
			if (header == null)
			{
				continue;
			}

			List<Integer> items = categories.get(Text.removeTags(header.getText()).trim());
			if (!items.contains(itemId))
			{
				items.add(itemId);
			}
			seen.add(itemId);
		}

		for (SeedVaultSnapshot.Seed seed : seeds)
		{
			if (!seen.contains(seed.getId()))
			{
				log.debug("Seed {} isn't shown in the vault, not updating categories", seed.getId());
				return null;
			}
		}

		List<SeedVaultSnapshot.Category> result = new ArrayList<>();
		categories.forEach((name, items) ->
		{
			if (!items.isEmpty())
			{
				result.add(new SeedVaultSnapshot.Category(name, items));
			}
		});
		return result;
	}

	/**
	 * @return how many of the item are in the seed vault, as last seen
	 */
	int getVaultQuantity(int itemId)
	{
		return quantities.getOrDefault(itemId, 0);
	}

	private void setCurrent(SeedVaultSnapshot snapshot)
	{
		current = snapshot;

		Map<Integer, Integer> map = new HashMap<>();
		if (snapshot != null && snapshot.getItems() != null)
		{
			for (SeedVaultSnapshot.Seed seed : snapshot.getItems())
			{
				map.put(seed.getId(), seed.getQuantity());
			}
		}
		quantities = map;
	}

	private void persist()
	{
		configManager.setRSProfileConfiguration(SeedVaultMemoryConfig.GROUP, CONFIG_KEY, gson.toJson(current));
	}

	private SeedVaultSnapshot load()
	{
		String json = configManager.getRSProfileConfiguration(SeedVaultMemoryConfig.GROUP, CONFIG_KEY);
		if (json == null)
		{
			return null;
		}

		try
		{
			return gson.fromJson(json, SeedVaultSnapshot.class);
		}
		catch (JsonSyntaxException e)
		{
			log.debug("Unable to read saved seed vault", e);
			return null;
		}
	}

	/**
	 * Looks up item details on the client thread, then hands them to the panel on the EDT
	 */
	private void show()
	{
		final SeedVaultPanel panel = this.panel;
		final SeedVaultSnapshot snapshot = current;
		if (panel == null)
		{
			return;
		}

		if (snapshot == null || snapshot.getItems() == null)
		{
			final boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
			SwingUtilities.invokeLater(() -> panel.showNoData(loggedIn));
			return;
		}

		Map<Integer, SeedVaultPanel.Entry> entries = new LinkedHashMap<>();
		for (SeedVaultSnapshot.Seed seed : snapshot.getItems())
		{
			ItemComposition composition = itemManager.getItemComposition(seed.getId());
			entries.put(seed.getId(), new SeedVaultPanel.Entry(
				seed.getId(),
				composition.getName(),
				seed.getQuantity(),
				itemManager.getItemPrice(seed.getId()),
				composition.getHaPrice(),
				itemManager.getImage(seed.getId(), seed.getQuantity(), true)
			));
		}

		List<SeedVaultPanel.Section> sections = null;
		if (config.groupByCategory() && snapshot.getCategories() != null)
		{
			sections = new ArrayList<>();
			Set<Integer> placed = new HashSet<>();
			for (SeedVaultSnapshot.Category category : snapshot.getCategories())
			{
				List<SeedVaultPanel.Entry> items = new ArrayList<>();
				for (int id : category.getItems())
				{
					SeedVaultPanel.Entry entry = entries.get(id);
					if (entry != null)
					{
						items.add(entry);
						placed.add(id);
					}
				}
				if (!items.isEmpty())
				{
					sections.add(new SeedVaultPanel.Section(category.getName(), items));
				}
			}

			List<SeedVaultPanel.Entry> other = new ArrayList<>();
			for (SeedVaultPanel.Entry entry : entries.values())
			{
				if (!placed.contains(entry.getId()))
				{
					other.add(entry);
				}
			}
			if (!other.isEmpty())
			{
				sections.add(new SeedVaultPanel.Section(OTHER_CATEGORY, other));
			}
		}

		final List<SeedVaultPanel.Entry> all = new ArrayList<>(entries.values());
		final List<SeedVaultPanel.Section> grouped = sections;
		final boolean needsCategories = config.groupByCategory() && snapshot.getCategories() == null;
		SwingUtilities.invokeLater(() -> panel.showVault(all, grouped, needsCategories));
	}
}

package com.seedvaultmemory;

import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import lombok.Value;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.QuantityFormatter;

class SeedVaultPanel extends PluginPanel
{
	private static final String WIKI_LOOKUP = "https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=";
	private static final Icon EXPANDED_ARROW = new ArrowIcon(true);
	private static final Icon COLLAPSED_ARROW = new ArrowIcon(false);

	@Value
	static class Entry
	{
		int id;
		String name;
		int quantity;
		long gePrice;
		int haPrice;
		AsyncBufferedImage image;
	}

	@Value
	static class Section
	{
		String name;
		List<Entry> entries;
	}

	private final IconTextField searchBar = new IconTextField();
	private final JLabel geLabel = new JLabel();
	private final JLabel haLabel = new JLabel();
	private final JPanel listPanel = new JPanel(new DynamicGridLayout(0, 1, 0, 2));

	private final Set<String> collapsed;
	private final Consumer<Set<String>> onCollapsedChanged;

	private List<Entry> entries = Collections.emptyList();
	// Null when not grouping by category
	private List<Section> sections;
	private boolean needsCategories;
	private boolean hasData;
	private boolean loggedIn;

	SeedVaultPanel(Collection<String> collapsed, Consumer<Set<String>> onCollapsedChanged)
	{
		this.collapsed = new LinkedHashSet<>(collapsed);
		this.onCollapsedChanged = onCollapsedChanged;

		setLayout(new BorderLayout(0, 8));

		geLabel.setHorizontalAlignment(SwingConstants.CENTER);
		haLabel.setHorizontalAlignment(SwingConstants.CENTER);
		JPanel totals = new JPanel(new GridLayout(1, 2));
		totals.setBorder(new EmptyBorder(0, 0, 4, 0));
		totals.add(geLabel);
		totals.add(haLabel);

		searchBar.setIcon(IconTextField.Icon.SEARCH);
		searchBar.setPreferredSize(new Dimension(PANEL_WIDTH - 20, 30));
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchBar.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchBar.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rebuild();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rebuild();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rebuild();
			}
		});

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		totals.setAlignmentX(LEFT_ALIGNMENT);
		searchBar.setAlignmentX(LEFT_ALIGNMENT);
		header.add(totals);
		header.add(searchBar);

		add(header, BorderLayout.NORTH);
		add(listPanel, BorderLayout.CENTER);

		showNoData(false);
	}

	void showNoData(boolean loggedIn)
	{
		this.hasData = false;
		this.loggedIn = loggedIn;
		this.entries = Collections.emptyList();
		this.sections = null;
		geLabel.setText(" ");
		haLabel.setText(" ");
		rebuild();
	}

	void showVault(List<Entry> entries, List<Section> sections, boolean needsCategories)
	{
		this.hasData = true;
		this.entries = entries;
		this.sections = sections;
		this.needsCategories = needsCategories;

		long ge = 0;
		long ha = 0;
		for (Entry e : entries)
		{
			ge += e.getGePrice() * e.getQuantity();
			ha += (long) e.getHaPrice() * e.getQuantity();
		}
		geLabel.setText("GE: " + QuantityFormatter.quantityToStackSize(ge));
		haLabel.setText("HA: " + QuantityFormatter.quantityToStackSize(ha));
		rebuild();
	}

	private void rebuild()
	{
		listPanel.removeAll();

		if (!hasData)
		{
			listPanel.add(message(loggedIn
				? "Open your seed vault at the Farming Guild to record what's in it."
				: "Log in to see your seed vault."));
		}
		else if (entries.isEmpty())
		{
			listPanel.add(message("Your seed vault is empty."));
		}
		else
		{
			String search = searchBar.getText().trim().toLowerCase(Locale.ENGLISH);
			boolean any = false;

			if (sections != null)
			{
				for (Section section : sections)
				{
					List<Entry> matches = filter(section.getEntries(), search);
					if (matches.isEmpty())
					{
						continue;
					}
					any = true;

					// Show everything that matches while searching, even in collapsed categories
					boolean expanded = !search.isEmpty() || !collapsed.contains(section.getName());
					listPanel.add(sectionHeader(section.getName(), matches.size(), expanded, search.isEmpty()));
					if (expanded)
					{
						matches.forEach(e -> listPanel.add(row(e)));
					}
				}
			}
			else
			{
				if (needsCategories)
				{
					listPanel.add(message("Open your seed vault again to load its categories."));
				}
				for (Entry e : filter(entries, search))
				{
					listPanel.add(row(e));
					any = true;
				}
			}

			if (!any)
			{
				listPanel.add(message("No seeds match your search."));
			}
		}

		listPanel.revalidate();
		listPanel.repaint();
	}

	private void toggle(String section)
	{
		if (!collapsed.remove(section))
		{
			collapsed.add(section);
		}
		onCollapsedChanged.accept(collapsed);
		rebuild();
	}

	private static List<Entry> filter(List<Entry> entries, String search)
	{
		if (search.isEmpty())
		{
			return entries;
		}
		List<Entry> matches = new ArrayList<>();
		for (Entry e : entries)
		{
			if (e.getName().toLowerCase(Locale.ENGLISH).contains(search))
			{
				matches.add(e);
			}
		}
		return matches;
	}

	private JPanel sectionHeader(String name, int count, boolean expanded, boolean collapsible)
	{
		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setBorder(new EmptyBorder(6, 2, 2, 2));

		JLabel arrow = new JLabel(expanded ? EXPANDED_ARROW : COLLAPSED_ARROW);
		arrow.setVisible(collapsible);

		JLabel title = new JLabel(name);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);

		JLabel size = new JLabel(String.valueOf(count));
		size.setFont(FontManager.getRunescapeSmallFont());
		size.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		header.add(arrow, BorderLayout.WEST);
		header.add(title, BorderLayout.CENTER);
		header.add(size, BorderLayout.EAST);

		if (collapsible)
		{
			header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			header.setToolTipText(expanded ? "Collapse " + name : "Expand " + name);
			header.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent event)
				{
					if (SwingUtilities.isLeftMouseButton(event))
					{
						toggle(name);
					}
				}
			});
		}

		return header;
	}

	private static JPanel row(Entry e)
	{
		JPanel row = new JPanel(new BorderLayout(10, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 2, 1, 2));
		row.setToolTipText(tooltip(e));

		JPopupMenu menu = new JPopupMenu();
		JMenuItem wiki = new JMenuItem("Open on OSRS Wiki");
		wiki.addActionListener(ev -> LinkBrowser.browse(WIKI_LOOKUP + e.getId()));
		menu.add(wiki);
		row.setComponentPopupMenu(menu);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				row.setBackground(ColorScheme.DARK_GRAY_COLOR);
			}
		});

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setInheritsPopupMenu(true);
		e.getImage().addTo(icon);
		row.add(icon, BorderLayout.WEST);

		JLabel name = new JLabel(e.getName());
		name.setInheritsPopupMenu(true);
		row.add(name, BorderLayout.CENTER);

		return row;
	}

	private static String tooltip(Entry e)
	{
		StringBuilder sb = new StringBuilder("<html>")
			.append(e.getName()).append(" x ").append(QuantityFormatter.formatNumber(e.getQuantity()));
		if (e.getGePrice() > 0)
		{
			sb.append("<br>GE: ").append(QuantityFormatter.quantityToStackSize(e.getGePrice() * e.getQuantity()))
				.append(" (").append(QuantityFormatter.formatNumber(e.getGePrice())).append(" ea)");
		}
		if (e.getHaPrice() > 0)
		{
			sb.append("<br>HA: ").append(QuantityFormatter.quantityToStackSize((long) e.getHaPrice() * e.getQuantity()))
				.append(" (").append(QuantityFormatter.formatNumber(e.getHaPrice())).append(" ea)");
		}
		return sb.append("</html>").toString();
	}

	private static JLabel message(String text)
	{
		JLabel label = new JLabel("<html>" + text + "</html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}

	/**
	 * A small filled triangle pointing down (expanded) or right (collapsed).
	 * Drawn rather than using text, since the arrow glyphs in fonts don't match in size.
	 */
	private static class ArrowIcon implements Icon
	{
		private static final int SIZE = 8;

		private final boolean down;

		ArrowIcon(boolean down)
		{
			this.down = down;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ColorScheme.BRAND_ORANGE);
			if (down)
			{
				g2.fillPolygon(new int[]{x, x + SIZE, x + SIZE / 2}, new int[]{y + 1, y + 1, y + SIZE - 1}, 3);
			}
			else
			{
				g2.fillPolygon(new int[]{x + 1, x + SIZE - 1, x + 1}, new int[]{y, y + SIZE / 2, y + SIZE}, 3);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}
}

