package com.seedvaultmemory;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Adds how many of the hovered seed are in the seed vault to the mouse tooltip
 */
class SeedVaultTooltipOverlay extends Overlay
{
	private final Client client;
	private final TooltipManager tooltipManager;
	private final SeedVaultMemoryPlugin plugin;
	private final SeedVaultMemoryConfig config;

	@Inject
	SeedVaultTooltipOverlay(Client client, TooltipManager tooltipManager, SeedVaultMemoryPlugin plugin,
		SeedVaultMemoryConfig config)
	{
		this.client = client;
		this.tooltipManager = tooltipManager;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showTooltips() || client.isMenuOpen())
		{
			return null;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return null;
		}

		Widget widget = entries[entries.length - 1].getWidget();
		if (widget == null || widget.getItemId() <= 0
			// The vault already shows its own quantities
			|| WidgetUtil.componentToInterface(widget.getId()) == InterfaceID.SEED_VAULT)
		{
			return null;
		}

		int quantity = plugin.getVaultQuantity(widget.getItemId());
		if (quantity > 0)
		{
			tooltipManager.add(new Tooltip("Seed vault: " + QuantityFormatter.formatNumber(quantity)));
		}
		return null;
	}
}

